(function(global){
  'use strict';
  const LF=global.LF;
  function htmlToText(html){const box=document.createElement('div');box.innerHTML=html||'';box.querySelectorAll('li[data-check-item]').forEach(li=>{const checked=li.querySelector('input')?.checked;li.insertAdjacentText('afterbegin',checked?'[x] ':'[ ] ');});return(box.innerText||box.textContent||'').replace(/\n{3,}/g,'\n\n').trim();}
  function htmlToMarkdown(html){return LF.organization?.mdFromHtml?.(html)||htmlToText(html);}
  async function saveText(name,data,type='text/plain;charset=utf-8'){
    const blob=data instanceof Blob?data:new Blob([data],{type});
    if(global.showSaveFilePicker){try{const handle=await showSaveFilePicker({suggestedName:name,types:[{description:'Text document',accept:{[type.split(';')[0]]:['.'+(name.split('.').pop()||'txt')]}}]});const writable=await handle.createWritable();await writable.write(blob);await writable.close();LF.toast('Saved to your chosen device location.','success');return true;}catch(err){if(err?.name==='AbortError')return false;console.warn('File System Access save failed; falling back to download.',err);}}
    LF.download(name,blob,type);return true;
  }
  async function exportNote(note,format='txt'){
    if(!note)return;const title=note.title||'Untitled',base=LF.slug(title),body=note.locked?'[Locked note body cannot be exported until unlocked.]':(note._unlockedContent??note.content??'');
    if(format==='md')return saveText(`${base}.md`,`# ${title}\n\n${htmlToMarkdown(body)}\n`,'text/markdown;charset=utf-8');
    if(format==='html'){const html=`<!doctype html><meta charset="utf-8"><title>${LF.escapeHtml(title)}</title><main><h1>${LF.escapeHtml(title)}</h1>${body}</main>`;return saveText(`${base}.html`,html,'text/html;charset=utf-8');}
    return saveText(`${base}.txt`,`${title}\n${'='.repeat(Math.min(72,Math.max(8,title.length)))}\n\n${htmlToText(body)}\n`,'text/plain;charset=utf-8');
  }
  LF.exporter={saveText,exportNote,htmlToText,htmlToMarkdown};
  LF.storageBridge={
    async saveNote(note){document.dispatchEvent(new CustomEvent('ourspace:storage-save-note',{detail:{note}}));return{ok:true,delegated:true};},
    async saveFolder(payload){document.dispatchEvent(new CustomEvent('ourspace:storage-save-folder',{detail:payload}));return{ok:true,delegated:true};},
    async syncAll(payload){document.dispatchEvent(new CustomEvent('ourspace:storage-sync-all',{detail:payload}));return{ok:true,delegated:true};}
  };
})(window);


