    currentDocumentText(){if(LF.editor?.record){const body=LF.editor.currentContent?.()??LF.editor.record._unlockedContent??LF.editor.record.content??'';return LF.stripHtml(body);}const active=LF.state?.activeRecord;if(active)return LF.stripHtml(active._unlockedContent??active.content??'');const preview=$('#readerPreview');return preview?.innerText||'';},
