  function rotate(){const src=state.canvas;if(!src?.width)return;const tmp=document.createElement('canvas');tmp.width=src.height;tmp.height=src.width;const c=tmp.getContext('2d');c.translate(tmp.width/2,tmp.height/2);c.rotate(Math.PI/2);c.drawImage(src,-src.width/2,-src.height/2);src.width=tmp.width;src.height=tmp.height;state.ctx=src.getContext('2d',{willReadFrequently:true});state.ctx.drawImage(tmp,0,0);refreshData();setStatus('Rotated 90° clockwise.','success');}
  function enhance(){const c=state.canvas;if(!c?.width)return setStatus('Choose an image first.','warning');const image=state.ctx.getImageData(0,0,c.width,c.height),d=image.data;for(let i=0;i<d.length;i+=4){const gray=.299*d[i]+.587*d[i+1]+.114*d[i+2],contrast=Math.max(0,Math.min(255,(gray-128)*1.55+128)),v=contrast>210?255:contrast<50?0:contrast;d[i]=d[i+1]=d[i+2]=v;}state.ctx.putImageData(image,0,0);refreshData();setStatus('Enhanced contrast for easier reading/OCR.','success');}
  function autoCrop(){const c=state.canvas;if(!c?.width)return setStatus('Choose an image first.','warning');const image=state.ctx.getImageData(0,0,c.width,c.height),d=image.data;let minX=c.width,minY=c.height,maxX=0,maxY=0;const step=Math.max(1,Math.floor(Math.min(c.width,c.height)/700));for(let y=0;y<c.height;y+=step)for(let x=0;x<c.width;x+=step){const i=(y*c.width+x)*4,lum=.299*d[i]+.587*d[i+1]+.114*d[i+2];if(lum<242&&d[i+3]>8){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}}const pad=18;minX=Math.max(0,minX-pad);minY=Math.max(0,minY-pad);maxX=Math.min(c.width-1,maxX+pad);maxY=Math.min(c.height-1,maxY+pad);const w=maxX-minX+1,h=maxY-minY+1;if(w<c.width*.18||h<c.height*.18)return setStatus('Could not find a clear page boundary. Try Enhance first or use Smart perspective crop.','warning');const cropped=state.ctx.getImageData(minX,minY,w,h);c.width=w;c.height=h;state.ctx=c.getContext('2d',{willReadFrequently:true});state.ctx.putImageData(cropped,0,0);refreshData();setStatus('Auto-cropped around the detected content.','success');}
  async function smartCrop(){const c=state.canvas;if(!c?.width)return setStatus('Choose an image first.','warning');setStatus('Loading the optional OpenCV document boundary engine…');try{if(!global.cv){global.Module=global.Module||{};await loadScript(OPENCV);await new Promise((resolve,reject)=>{let tries=0;const tick=()=>{if(global.cv?.Mat)return resolve();if(++tries>100)return reject(new Error('OpenCV did not finish loading.'));setTimeout(tick,100);};tick();});}const mod=await import(DOCSCAN),scanner=new mod.DocumentScanner(),cropped=scanner.crop(c);if(!cropped?.width)throw new Error('No document boundary was detected.');c.width=cropped.width;c.height=cropped.height;state.ctx=c.getContext('2d',{willReadFrequently:true});state.ctx.drawImage(cropped,0,0);refreshData();setStatus('Perspective-corrected document crop applied.','success');}catch(err){setStatus(`Smart crop unavailable: ${err.message}. Basic crop still works.`,`warning`);}}
  async function ocr(){if(state.busy)return;if(!state.dataUrl)return setStatus('Choose or capture an image first.','warning');state.busy=true;setProgress(1);setStatus('Loading OCR…');try{if(!global.Tesseract)await loadScript(TESS);if(!global.Tesseract?.recognize)throw new Error('Tesseract OCR did not initialize.');const res=await global.Tesseract.recognize(state.dataUrl,'eng',{logger:m=>{if(typeof m?.progress==='number')setProgress(Math.round(m.progress*100));if(m?.status)setStatus(`OCR: ${String(m.status).replace(/_/g,' ')}`);}});const text=String(res?.data?.text||'').replace(/\r\n/g,'\n').replace(/[ \t]+\n/g,'\n').replace(/\n{4,}/g,'\n\n\n').trim();$('#scanText').value=text;setProgress(100);setStatus(text?'Text extracted. Review it before saving.':'OCR completed but did not find text.',text?'success':'warning');}catch(err){setStatus(`OCR failed: ${err.message}`,'danger');}finally{state.busy=false;}}
  async function saveAsNote(){const text=$('#scanText').value.trim();if(!text)return setStatus('There is no extracted text to save.','warning');const title=$('#scanTitle').value.trim()||'Scanned document',folderId=$('#scanFolder').value,owner=$('#scanOwner').value,note=await LF.store.put({type:'note',noteKind:'note',owner,folderId,title,content:`<p>${LF.escapeHtml(text).replace(/\n/g,'<br>')}</p>`,tags:['scan','ocr']});if(state.dataUrl){const blob=dataUrlToBlob(state.dataUrl),id=LF.uid('attachment');await LF.store.putBlob({id,ownerId:note.id,name:state.name||`${LF.slug(title)}.png`,mimeType:blob.type,blob,metadata:{source:'scanner'}});await LF.store.put({type:'attachment',id,owner:note.owner,ownerId:note.id,name:state.name||`${LF.slug(title)}.png`,mimeType:blob.type,size:blob.size,source:'scanner'});}LF.toast('Scanned document saved as a note.','success');LF.app?.openRecord?.(note);}
  async function appendToNote(){const text=$('#scanText').value.trim();if(!text)return setStatus('There is no extracted text to append.','warning');const id=$('#scanAppendNote').value;if(!id)return setStatus('Choose a note to append to.','warning');const note=await LF.store.get('note',id);if(!note)return;const content=`${note.content||''}<hr><h2>${LF.escapeHtml($('#scanTitle').value.trim()||'Scanned text')}</h2><p>${LF.escapeHtml(text).replace(/\n/g,'<br>')}</p>`;await LF.store.put({...note,content});LF.toast('Scanned text appended to the note.','success');}
  LF.extraViews.scan=async app=>{const folders=await LF.store.list('noteFolder',{owner:'all',sort:'title-asc'}),map=new Map(folders.map(f=>[f.id,f])),tree=LF.organization?.sortTree?.(folders)||folders,notes=await LF.store.list('note',{owner:'all',sort:'updated-desc'});app.root.innerHTML=`<section class="view-page scan-view"><header class="view-header"><div><p class="eyebrow">Accessibility tools</p><h1>Scan & extract text</h1><p>Photograph or upload a page, clean it up, run browser OCR, then save the text as a note, append it, export it, or read it aloud.</p></div><div class="header-actions"><button id="scanChoose" class="button button--primary" type="button">📷 Choose / camera</button><button id="scanClear" class="button button--ghost" type="button">Clear</button></div></header><div id="scanStatus" class="tool-status" role="status" aria-live="polite">Scanner ready.</div><progress id="scanProgress" class="scan-progress" value="0" max="100">0%</progress><div class="scan-grid"><section class="panel scan-image-panel"><div class="section-heading"><div><p class="eyebrow">1. Page image</p><h2>Prepare the scan</h2></div></div><canvas id="scanCanvas" class="scan-canvas" aria-label="Scanned page preview"></canvas><div class="button-row wrap"><button id="scanRotate" type="button">↻ Rotate</button><button id="scanEnhance" type="button">◐ Enhance</button><button id="scanCrop" type="button">⌗ Auto crop</button><button id="scanSmartCrop" type="button">◇ Smart perspective crop</button><button id="scanOcr" class="button button--primary" type="button">OCR → text</button></div><p class="small muted">Basic enhancement/crop is built in. Smart perspective crop loads the optional OpenCV browser engine only when requested.</p></section><section class="panel scan-text-panel"><div class="section-heading"><div><p class="eyebrow">2. Extracted text</p><h2>Review & use</h2></div><button id="scanRead" class="button button--secondary" type="button">▶ Read text</button></div><label class="field">Title<input id="scanTitle" value="Scanned document"></label><textarea id="scanText" class="scan-textarea" rows="18" placeholder="OCR text appears here. You can edit mistakes before saving."></textarea><div class="form-grid"><label class="field">Owner<select id="scanOwner"><option value="william">William</option><option value="shared">Shared</option><option value="jasper">Jasper</option></select></label><label class="field">Folder<select id="scanFolder"><option value="">Unfiled</option>${tree.map(f=>`<option value="${f.id}">${'— '.repeat(Math.min(f._depth||0,6))}${LF.escapeHtml(f.title)} · ${LF.profileLabel(f.owner)}</option>`).join('')}</select></label><label class="field field--wide">Append to existing note<select id="scanAppendNote"><option value="">Choose a note…</option>${notes.slice(0,250).map(n=>`<option value="${n.id}">${LF.escapeHtml(n.title)} · ${LF.profileLabel(n.owner)}</option>`).join('')}</select></label></div><div class="button-row wrap"><button id="scanSaveNote" class="button button--primary" type="button">Save as note</button><button id="scanAppend" type="button">Append to note</button><button id="scanExportTxt" type="button">Export TXT</button><button id="scanCopy" type="button">Copy text</button></div></section></div></section>`;state.canvas=$('#scanCanvas');state.ctx=state.canvas.getContext('2d',{willReadFrequently:true});if(state.dataUrl){const img=new Image();img.onload=()=>{state.canvas.width=img.width;state.canvas.height=img.height;state.ctx.drawImage(img,0,0);};img.src=state.dataUrl;}$('#scanOwner').value=ownerForNew();$('#scanChoose').onclick=()=>document.getElementById('scanInput').click();document.getElementById('scanInput').onchange=e=>{chooseImage(e.target.files[0]);e.target.value='';};$('#scanRotate').onclick=rotate;$('#scanEnhance').onclick=enhance;$('#scanCrop').onclick=autoCrop;$('#scanSmartCrop').onclick=smartCrop;$('#scanOcr').onclick=ocr;$('#scanSaveNote').onclick=saveAsNote;$('#scanAppend').onclick=appendToNote;$('#scanRead').onclick=()=>LF.reader?.speakText?.($('#scanText').value,'scanned text');$('#scanExportTxt').onclick=()=>LF.exporter?.saveText?.(`${LF.slug($('#scanTitle').value||'scanned-document')}.txt`,$('#scanText').value,'text/plain;charset=utf-8');$('#scanCopy').onclick=async()=>{try{await navigator.clipboard.writeText($('#scanText').value);LF.toast('Text copied.','success');}catch(_){$('#scanText').focus();$('#scanText').select();LF.toast('Clipboard access was blocked; the text is selected for manual copy.','warning');}};$('#scanClear').onclick=()=>{state.dataUrl='';state.name='';state.canvas.width=1;state.canvas.height=1;$('#scanText').value='';$('#scanTitle').value='Scanned document';setProgress(0);setStatus('Scanner cleared.');};};
