    normalizeChecks(){LF.journal.normalizeChecklistHtml(this.el);}
    cleanPaste(e){const html=e.clipboardData?.getData('text/html'),text=e.clipboardData?.getData('text/plain');if(!html)return;e.preventDefault();const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('script,style,iframe,object,embed,form,button,meta,link').forEach(x=>x.remove());box.querySelectorAll('*').forEach(x=>[...x.attributes].forEach(a=>{if(/^on/i.test(a.name)||a.name==='style')x.removeAttribute(a.name);}));document.execCommand('insertHTML',false,box.innerHTML||LF.escapeHtml(text));this.onInput();}
