    async save(){if(!this.record||!this.el)return;clearTimeout(this.saveTimer);const content=this.currentContent(),owner=document.querySelector('#editorOwner')?.value||this.record.owner||'shared',noteKind=document.querySelector('#editorKind')?.value||this.record.noteKind||'note';let patch={...this.record,title:this.titleEl.value.trim()||'Untitled',tags:LF.parseTags(this.tagsEl.value),owner,noteKind,folderId:document.querySelector('#editorFolder')?.value||''};if(noteKind==='journal'&&!patch.dateKey)patch.dateKey=LF.localDateKey();if(this.record.locked&&this.record._unlockPassword){patch.encrypted=await LF.security.encrypt(content,this.record._unlockPassword);patch.content='';patch._unlockedContent=content;}else patch.content=content;this.record=await LF.store.put(patch);this.dirty=false;this.status('Saved locally','success');document.querySelector('.editor-shell')?.setAttribute('data-note-owner',owner);LF.events.emit('editor:saved',this.record);return this.record;}
    insertHtml(html){this.el.focus();document.execCommand('insertHTML',false,html);this.onInput();}
