    insertTimestamp(){const now=new Date(),stamp=new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(now);this.insertHtml(`<span class="timestamp">${LF.escapeHtml(stamp)}</span> `);}
    async insertLink(){const selection=window.getSelection()?.toString()||'',result=await LF.dialog({title:'Insert link',body:`<label class="field">Link text<input id="linkText" value="${LF.escapeAttr(selection)}"></label><label class="field">URL<input id="linkUrl" type="url" placeholder="https://"></label>`,confirmText:'Insert'});if(!result)return;const text=result.root.querySelector('#linkText').value.trim()||'link',url=result.root.querySelector('#linkUrl').value.trim();if(!url)return;this.insertHtml(`<a href="${LF.escapeAttr(url)}" target="_blank" rel="noopener">${LF.escapeHtml(text)}</a>`);}
    async insertWikiLink(){const notes=(await LF.store.list('note',{owner:'all',sort:'title-asc'})).filter(x=>x.id!==this.record.id);if(!notes.length){LF.toast('Create another note first.','warning');return;}const result=await LF.dialog({title:'Link another note',body:`<label class="field">Note<select id="wikiDoc">${notes.map(n=>`<option value="${LF.escapeAttr(n.title)}">${LF.escapeHtml(n.title)} · ${LF.profileLabel(n.owner)}</option>`).join('')}</select></label>`,confirmText:'Insert link'});if(!result)return;this.el.focus();document.execCommand('insertText',false,`[[${result.root.querySelector('#wikiDoc').value}]]`);this.onInput();}
    async attachFiles(files,{scan=false}={}){for(const file of files){if(!file)continue;const blob=await LF.store.putBlob({ownerId:this.record.id,name:file.name||`photo-${Date.now()}.jpg`,mimeType:file.type||'application/octet-stream',blob:file,metadata:{scan}});await LF.store.put({type:'attachment',id:blob.id,ownerId:this.record.id,owner:this.record.owner||'shared',name:blob.name,mimeType:blob.mimeType,size:blob.size,scan});if(/^image\//.test(blob.mimeType)){const url=URL.createObjectURL(file);this.insertHtml(`<figure data-attachment-id="${blob.id}"><img src="${url}" alt="${LF.escapeAttr(scan?'Captured image':file.name)}"><figcaption>${LF.escapeHtml(file.name)}</figcaption></figure><p><br></p>`);}else this.insertHtml(`<p class="attachment-chip" data-attachment-id="${blob.id}">📎 ${LF.escapeHtml(file.name)} <small>${Math.ceil(file.size/1024)} KB</small></p>`);}document.getElementById('attachmentInput').value='';document.getElementById('scanInput').value='';}
